`timescale 1ns/1ps
module tb_mlkem_xof;reg clk=0,rst_n=0,init_valid=0,use_generic_input=0,squeeze_req_valid=0,out_ready=0;reg[255:0]seed;reg[7:0]index0,index1;reg[271:0]generic_input;reg[31:0]squeeze_len_bytes;wire init_ready,squeeze_req_ready,out_valid;wire[31:0]out_data;wire[3:0]out_keep;wire out_last,context_valid,busy,done,error;reg[4095:0]expected;integer fd,rc,i0,i1,olen,vectors,bytes,requests,pos,chunk,got,n,k,watchdog;reg[1023:0]path;always #5 clk=~clk;
mlkem_xof dut(.clk(clk),.rst_n(rst_n),.init_valid(init_valid),.init_ready(init_ready),.seed(seed),.index0(index0),.index1(index1),.use_generic_input(use_generic_input),.generic_input(generic_input),.squeeze_req_valid(squeeze_req_valid),.squeeze_req_ready(squeeze_req_ready),.squeeze_len_bytes(squeeze_len_bytes),.out_valid(out_valid),.out_ready(out_ready),.out_data(out_data),.out_keep(out_keep),.out_last(out_last),.context_valid(context_valid),.busy(busy),.done(done),.error(error));
task reset;begin @(negedge clk);rst_n=0;init_valid=0;squeeze_req_valid=0;out_ready=0;@(posedge clk);#1;@(negedge clk);rst_n=1;end endtask
task get_chunk;input integer len;input integer base;begin while(!squeeze_req_ready)@(posedge clk);@(negedge clk);squeeze_len_bytes=len;squeeze_req_valid=1;@(posedge clk);#1;@(negedge clk);squeeze_req_valid=0;got=0;watchdog=0;while(got<len&&watchdog<30000)begin @(negedge clk);out_ready=((watchdog+requests)%4)!=0;@(posedge clk);watchdog=watchdog+1;if(out_valid&&out_ready)begin n=(out_keep==1)?1:(out_keep==3)?2:(out_keep==7)?3:4;for(k=0;k<n;k=k+1)begin bytes=bytes+1;if(out_data[8*k+:8]!==expected[8*(base+got+k)+:8])$fatal(1,"xof vector=%0d byte=%0d",vectors,base+got+k);end got=got+n;if(out_last!==(got==len))$fatal(1,"last");end end if(watchdog>=30000)$fatal(1,"watchdog");@(negedge clk);out_ready=0;requests=requests+1;end endtask
initial begin vectors=0;bytes=0;requests=0;reset();if(!$value$plusargs("VECTORS=%s",path))$fatal(1,"vectors");fd=$fopen(path,"r");while(!$feof(fd))begin rc=$fscanf(fd,"%d %d %d %h %h\n",i0,i1,olen,seed,expected);if(rc==5)begin while(!init_ready)@(posedge clk);@(negedge clk);index0=i0;index1=i1;use_generic_input=vectors[0];generic_input={i1[7:0],i0[7:0],seed};init_valid=1;@(posedge clk);#1;@(negedge clk);init_valid=0;watchdog=0;while(!context_valid&&watchdog<20000)begin @(posedge clk);watchdog=watchdog+1;end if(watchdog>=20000)$fatal(1,"init watchdog");pos=0;while(pos<olen)begin chunk=(requests%9)+1;if(chunk>olen-pos)chunk=olen-pos;get_chunk(chunk,pos);pos=pos+chunk;end if(error)$fatal(1,"error");vectors=vectors+1;end end $fclose(fd);if(vectors!=64)$fatal(1,"count");reset();$display("PASS tb_mlkem_xof vectors=%0d bytes=%0d squeeze_requests=%0d",vectors,bytes,requests);$finish;end
endmodule
